"use client";
import { useEffect, useRef, useState } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import MaskedText from "./masked-text"; // ✅ import your masked text component

function MobileMenu({ isOpen, onClose }) {
  const menuRef = useRef(null);
  const tl = useRef(null);

  useEffect(() => {
    if (!menuRef.current) return;

    if (tl.current) tl.current.kill();

    tl.current = gsap.timeline({
      defaults: { ease: "power3.inOut", duration: 1 },
    });

    if (isOpen) {
      gsap.set(menuRef.current, {
        y: "-100%",
        opacity: 0,
        pointerEvents: "auto",
      });

      tl.current.to(menuRef.current, { y: "0%", opacity: 1 });
    } else {
      tl.current.to(menuRef.current, {
        y: "-100%",
        opacity: 0,
        duration: 0.8,
        onComplete: () => {
          gsap.set(menuRef.current, { pointerEvents: "none" });
        },
      });
    }
  }, [isOpen]);

  return (
    <div
      ref={menuRef}
      className="fixed left-0 top-0 w-full h-screen bg-black text-white flex flex-col items-start justify-center gap-8 px-2 md:hidden z-[80] overflow-hidden pointer-events-none"
      style={{ transformOrigin: "top center" }}
    >
      <button
        onClick={onClose}
        className="mt-4 text-sm opacity-70 hover:opacity-100 transition"
      >
        Let&apos;s Talk
      </button>

      <section className="flex flex-col">
        {["Home", "About", "Works", "Service", "Contact"].map((text) => (
          <Link
            key={text}
            href={`/${text === "Home" ? "" : text.toLowerCase()}`}
            onClick={onClose}
            className="overflow-hidden"
          >
            <MaskedText
              text={text}
              className="text-5xl font-light text-white hover:opacity-70 transition-opacity"
              indent={false}
              positioning=""
              forcePlay={isOpen} // 👈 replays animation whenever menu opens
            />
          </Link>
        ))}
      </section>
    </div>
  );
}

export default function Navbar({
  initialColor = "white",
  adaptiveMode = true,
  blendMode = "difference",
}) {
  gsap.registerPlugin(ScrollTrigger);
  const pathname = usePathname();
  const navbarRef = useRef(null);
  const textRef = useRef(null);
  const svgNavRef = useRef(null);
  const logoContainerRef = useRef(null);
  const scrollTriggersRef = useRef([]);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    scrollTriggersRef.current.forEach((trigger) => trigger?.kill?.());
    scrollTriggersRef.current = [];

    if (textRef.current) gsap.set(textRef.current, { y: 0, opacity: 1 });
    if (svgNavRef.current)
      gsap.set(svgNavRef.current, { opacity: 0, y: "100%" });

    ScrollTrigger.refresh();
  }, [pathname]);

  useEffect(() => {
    if (!navbarRef.current) return;
    gsap.set(navbarRef.current, { opacity: 1, y: 0 });
    const navAnimation = gsap.from(navbarRef.current, {
      y: -50,
      opacity: 0,
      duration: 1,
      ease: "power2.out",
      delay: 0.5,
    });
    return () => navAnimation.kill();
  }, [pathname]);

  useEffect(() => {
    if (!textRef.current || !svgNavRef.current) return;
    const ctx = gsap.context(() => {
      const trigger = ScrollTrigger.create({
        start: "top -100",
        end: "bottom top",
        onEnter: () => {
          gsap.to(textRef.current, {
            y: "-100%",
            opacity: 0.3,
            duration: 0.4,
            ease: "power2.inOut",
          });
          gsap.to(svgNavRef.current, {
            opacity: 1,
            y: 0,
            duration: 0.4,
            ease: "power2.inOut",
          });
        },
        onLeaveBack: () => {
          gsap.to(textRef.current, {
            y: 0,
            opacity: 1,
            duration: 0.4,
            ease: "power2.inOut",
          });
          gsap.to(svgNavRef.current, {
            opacity: 0,
            y: "100%",
            duration: 0.4,
            ease: "power2.inOut",
          });
        },
      });
      scrollTriggersRef.current.push(trigger);
    });
    return () => {
      scrollTriggersRef.current.forEach((t) => t?.kill?.());
      scrollTriggersRef.current = [];
      ctx.revert();
    };
  }, [pathname]);

  const getNavbarStyle = () => {
    const baseStyle = {};
    if (menuOpen) {
      return {
        ...baseStyle,
        backgroundColor: "black",
        color: "white",
        mixBlendMode: "normal",
      };
    }
    if (adaptiveMode) {
      return {
        ...baseStyle,
        color: "white",
        mixBlendMode: "difference",
      };
    } else {
      return {
        ...baseStyle,
        color: initialColor,
        mixBlendMode: blendMode,
      };
    }
  };

  const navbarStyle = getNavbarStyle();

  return (
    <>
      <section
        ref={navbarRef}
        className={`fixed top-0 left-0 w-full h-[80px] z-[90] flex items-center justify-between px-2 sm:px-10 transition-colors duration-500 ${
          menuOpen ? "bg-black" : "bg-transparent md:bg-transparent"
        }`}
        style={navbarStyle}
      >
        <div className="flex items-center gap-2">
          <div ref={logoContainerRef} className="relative overflow-hidden">
            <p ref={textRef} className="text font-medium whitespace-nowrap">
              The Brand Catalyst
            </p>
            <svg
              ref={svgNavRef}
              className="absolute inset-0"
              viewBox="0 0 1364 253"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
              preserveAspectRatio="xMidYMid meet"
              style={{ width: "50%", height: "100%" }}
            >
              {/* svg paths unchanged */}
            </svg>
          </div>
        </div>

        <div className="hidden md:flex items-center gap-6 text-sm">
          <Link href="/" className="hover:opacity-70 transition-opacity">
            Home
          </Link>
          <Link href="/about" className="hover:opacity-70 transition-opacity">
            About
          </Link>
          <Link href="/works" className="hover:opacity-70 transition-opacity">
            Works
          </Link>
          <Link href="/service" className="hover:opacity-70 transition-opacity">
            Service
          </Link>
          <Link href="/contact" className="hover:opacity-70 transition-opacity">
            Contact
          </Link>
          <div className="cursor-pointer px-4 py-2 flex gap-1 items-center transition-all duration-200 hover:mix-blend-difference">
            Let&apos;s Talk
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 20 20"
              fill="currentColor"
              className="size-5"
            >
              <path
                fillRule="evenodd"
                d="M5.22 14.78a.75.75 0 0 0 1.06 0l7.22-7.22v5.69a.75.75 0 0 0 1.5 0v-7.5a.75.75 0 0 0-.75-.75h-7.5a.75.75 0 0 0 0 1.5h5.69l-7.22 7.22a.75.75 0 0 0 0 1.06Z"
                clipRule="evenodd"
              />
            </svg>
          </div>
        </div>

        <div className="md:hidden flex items-center relative">
          <button
            type="button"
            onClick={() => setMenuOpen(!menuOpen)}
            className="text-white bg-[#2e2e2e] px-4 py-2 text-sm rounded-sm active:scale-95 transition-all"
          >
            {menuOpen ? "Close" : "Menu"}
          </button>
        </div>
      </section>

      <MobileMenu isOpen={menuOpen} onClose={() => setMenuOpen(false)} />
    </>
  );
}
